script:
import time, json

def wait_form():
    t0 = time.time()
    while time.time() - t0 < 15:
        if js("!!document.getElementById('inputName') && !!document.getElementById('inputHour')"):
            return
        time.sleep(0.15)
    raise RuntimeError("UNAVAILABLE: form chưa xuất hiện")

def stable_hours():
    # Chờ danh sách giờ ổn định (không đổi trong ~0.6s) sau khi đổi chi nhánh/ngày/số người
    time.sleep(0.6)
    last, same, t0 = None, 0, time.time()
    while time.time() - t0 < 15:
        cur = js("[...document.getElementById('inputHour').options].map(o=>o.value+'|'+o.text+'|'+o.disabled).join(';')")
        same = same + 1 if cur == last else 0
        if same >= 3:
            return
        last = cur
        time.sleep(0.2)
    raise RuntimeError("UNAVAILABLE: danh sách giờ không ổn định")

def pick(sid, cond, label):
    # Chọn option khớp CHÍNH XÁC theo biểu thức cond (biến o), gán value + dispatch input/change
    r = js(f"""(()=>{{const s=document.getElementById({json.dumps(sid)});
const o=[...s.options].find(o=>({cond}));
if(!o)return 'NOTFOUND';if(o.disabled)return 'DISABLED';
s.value=o.value;s.dispatchEvent(new Event('input',{{bubbles:true}}));s.dispatchEvent(new Event('change',{{bubbles:true}}));return s.value;}})()""")
    if r == 'NOTFOUND':
        raise RuntimeError(f"UNAVAILABLE: không có {label} khớp chính xác")
    if r == 'DISABLED':
        raise RuntimeError(f"UNAVAILABLE: {label} bị disabled")
    return r

def set_text(sid, text):
    js(f"(()=>{{const e=document.getElementById({json.dumps(sid)});e.scrollIntoView({{block:'center'}});e.focus();}})()")
    x, y = js(f"(()=>{{const r=document.getElementById({json.dumps(sid)}).getBoundingClientRect();return [r.x+r.width/2,r.y+r.height/2]}})()")
    click_at_xy(x, y)
    cdp('Input.dispatchKeyEvent', type='rawKeyDown', key='a', code='KeyA', commands=['selectAll'])
    cdp('Input.dispatchKeyEvent', type='keyUp', key='a', code='KeyA')
    type_text(text)
    press_key('Tab')
    time.sleep(0.3)
    if js(f"document.getElementById({json.dumps(sid)}).value") != text:
        # Dự phòng cho ô readOnly (datepicker): gán qua native setter
        js(f"""(()=>{{const e=document.getElementById({json.dumps(sid)});
const d=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value');d.set.call(e,{json.dumps(text)});
e.dispatchEvent(new Event('input',{{bubbles:true}}));e.dispatchEvent(new Event('change',{{bubbles:true}}));}})()""")
        time.sleep(0.3)

def get_val(sid):
    return js(f"(()=>{{const e=document.getElementById({json.dumps(sid)});return e?e.value:null}})()")

wait_form()

# 1. Chi nhánh (trước tiên)
if BRANCH is None:
    branch_cond = "o.value==='48'"
else:
    branch_cond = f"o.text.trim()=={json.dumps(BRANCH)} || o.text.split(' - ')[0].trim()=={json.dumps(BRANCH)}"
restaurant_val = pick('inputRestaurant', branch_cond, 'chi nhánh')
time.sleep(0.5)

# 2. Ngày
date_expected = DATE_DMY
if js("document.getElementById('inputDate').tagName") == 'SELECT':
    lab = {1: 'Ngày mai', 2: 'Ngày kia'}.get(DAY_OFFSET)
    date_expected = pick('inputDate', f"o.text.trim()=={json.dumps(lab)} || o.value=={json.dumps(DATE_DMY)}", 'ngày')
else:
    set_text('inputDate', DATE_DMY)
time.sleep(0.5)

# 3. Số người
set_text('inputNumber', str(PARTY))
time.sleep(0.5)

# 4. Thông tin liên hệ (không ảnh hưởng danh sách giờ)
set_text('inputName', NAME)
set_text('inputPhone', PHONE)
if js("!!document.getElementById('inputEmail')") and EMAIL:
    set_text('inputEmail', EMAIL)

# 5. Giờ và phút (chỉ sau khi danh sách giờ ổn định)
stable_hours()
H = str(int(HHMM[:2]))
M = HHMM[3:5]
hour_val = pick('inputHour', f"o.value==={json.dumps(H)}", 'giờ')
minute_val = pick('inputMinute', f"o.value==={json.dumps(M)}", 'phút')
time.sleep(0.3)

# 6. Đọc lại giá trị thật và đối chiếu
expected = {
    'inputName': NAME, 'inputPhone': PHONE, 'inputEmail': EMAIL,
    'inputDate': date_expected, 'inputHour': hour_val, 'inputMinute': minute_val,
    'inputNumber': str(PARTY), 'inputRestaurant': restaurant_val,
}
mismatch = []
for k, v in expected.items():
    got = get_val(k)
    if got is None and k == 'inputEmail':
        continue
    if got != v:
        mismatch.append(f"{k}: mong {v!r}, thực {got!r}")
if mismatch:
    raise RuntimeError("MISMATCH: " + "; ".join(mismatch))
print("OK: đã điền form", {k: get_val(k) for k in expected if get_val(k) is not None})
